//! Ambient music from the user's own files (decision D-016). The default theme, "Morning Lounge",
//! is generated by the UI; this module turns the sources the user picked (files, folders, albums in
//! the library) into a playlist and remembers exactly which files may be streamed, so the media
//! protocol never serves a path that came from a URL.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::RwLock;

use rusqlite::params;
use serde::{Deserialize, Serialize};
use tauri::State;
use walkdir::WalkDir;

use crate::error::AppResult;
use crate::library::blocking;
use crate::{files, formats, AppState, Library};

/// Formats WebView2 can play without extra codecs.
const PLAYABLE: &[&str] = &["mp3", "m4a", "aac", "flac", "ogg", "oga", "opus", "wav", "webm"];
const MAX_TRACKS: usize = 10_000;

#[derive(Default)]
pub struct AmbientState {
    next_generation: AtomicU64,
    /// The current playlist's generation and files; a track's id is its index.
    playlist: RwLock<(u64, Vec<PathBuf>)>,
}

impl AmbientState {
    /// The file behind a track of the current playlist. Stale generations resolve to nothing.
    pub fn track(&self, generation: u64, index: usize) -> Option<PathBuf> {
        let playlist = self.playlist.read().ok()?;
        (playlist.0 == generation).then(|| playlist.1.get(index).cloned()).flatten()
    }
}

#[derive(Debug, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum MusicSource {
    File { path: String },
    Folder { path: String },
    Item { id: i64 },
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct AmbientTrack {
    pub id: usize,
    pub title: String,
    pub artist: Option<String>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Playlist {
    pub generation: u64,
    pub tracks: Vec<AmbientTrack>,
    /// Sources that no longer exist (a moved file or folder, an album removed from the library).
    pub unavailable: usize,
    /// More than `MAX_TRACKS` files were found; the rest were left out.
    pub truncated: bool,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TrackDetails {
    pub title: Option<String>,
    pub artist: Option<String>,
    pub album: Option<String>,
}

pub fn is_playable(path: &Path) -> bool {
    path.extension()
        .and_then(|ext| ext.to_str())
        .is_some_and(|ext| PLAYABLE.contains(&ext.to_ascii_lowercase().as_str()))
}

pub fn mime_type(path: &Path) -> &'static str {
    match path.extension().and_then(|ext| ext.to_str()).map(str::to_ascii_lowercase).as_deref() {
        Some("mp3") => "audio/mpeg",
        Some("m4a") => "audio/mp4",
        Some("aac") => "audio/aac",
        Some("flac") => "audio/flac",
        Some("ogg" | "oga" | "opus") => "audio/ogg",
        Some("wav") => "audio/wav",
        Some("webm") => "audio/webm",
        _ => "application/octet-stream",
    }
}

fn stem(path: &Path) -> String {
    path.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default()
}

struct Builder {
    tracks: Vec<(PathBuf, AmbientTrack)>,
    seen: HashSet<String>,
    unavailable: usize,
    truncated: bool,
}

impl Builder {
    fn push(&mut self, path: PathBuf, title: Option<String>, artist: Option<String>) {
        if self.tracks.len() >= MAX_TRACKS {
            self.truncated = true;
            return;
        }
        if !self.seen.insert(path.to_string_lossy().to_lowercase()) {
            return;
        }
        let title = title.filter(|t| !t.trim().is_empty()).unwrap_or_else(|| stem(&path));
        let id = self.tracks.len();
        self.tracks.push((path, AmbientTrack { id, title, artist }));
    }

    fn folder(&mut self, dir: &Path) {
        if !dir.is_dir() {
            self.unavailable += 1;
            return;
        }
        let walker = WalkDir::new(dir)
            .sort_by(|a, b| files::natural_cmp(&a.file_name().to_string_lossy(), &b.file_name().to_string_lossy()));
        for entry in walker.into_iter().filter_map(Result::ok) {
            if entry.file_type().is_file() && is_playable(entry.path()) {
                self.push(entry.into_path(), None, None);
            }
            if self.truncated {
                break;
            }
        }
    }

    /// An album (or any audio item) in the library: the files of its primary digital copy, in order.
    fn item(&mut self, library: Option<&Library>, id: i64) -> AppResult<()> {
        let Some(library) = library else {
            self.unavailable += 1;
            return Ok(());
        };
        let rows: Vec<(String, String, Option<String>, Option<String>)> = library.db.with(|conn| {
            let mut stmt = conn.prepare(
                "SELECT f.path, f.storage, p.title, \
                   (SELECT pe.name FROM item_people ip JOIN people pe ON pe.id = ip.person_id \
                    WHERE ip.item_id = ?1 ORDER BY ip.position LIMIT 1) \
                 FROM files f LEFT JOIN parts p ON p.id = f.part_id \
                 WHERE f.status = 'ok' AND f.version_id = (SELECT v.id FROM versions v \
                   WHERE v.item_id = ?1 AND v.kind = 'digital' ORDER BY v.is_primary DESC, v.id LIMIT 1) \
                 ORDER BY f.position",
            )?;
            let rows = stmt
                .query_map(params![id], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)))?
                .collect::<Result<_, _>>()?;
            Ok(rows)
        })?;
        if rows.is_empty() {
            self.unavailable += 1;
        }
        for (path, storage, title, artist) in rows {
            let path = library.folder.resolve(&path, &storage);
            if is_playable(&path) {
                self.push(path, title, artist);
            }
        }
        Ok(())
    }
}

/// Resolves the user's music sources into the playlist that `digitify://ambient/...` may stream.
#[tauri::command]
pub async fn ambient_playlist(
    state: State<'_, AppState>,
    ambient: State<'_, AmbientState>,
    sources: Vec<MusicSource>,
) -> AppResult<Playlist> {
    let generation = ambient.next_generation.fetch_add(1, Ordering::SeqCst) + 1;
    let library = state.library().ok();
    let built = blocking(move || {
        let mut builder = Builder { tracks: Vec::new(), seen: HashSet::new(), unavailable: 0, truncated: false };
        for source in sources {
            match source {
                MusicSource::File { path } => {
                    let path = PathBuf::from(path);
                    if path.is_file() && is_playable(&path) {
                        builder.push(path, None, None);
                    } else {
                        builder.unavailable += 1;
                    }
                }
                MusicSource::Folder { path } => builder.folder(Path::new(&path)),
                MusicSource::Item { id } => builder.item(library.as_deref(), id)?,
            }
        }
        Ok(builder)
    })
    .await?;

    let (paths, tracks): (Vec<PathBuf>, Vec<AmbientTrack>) = built.tracks.into_iter().unzip();
    if let Ok(mut playlist) = ambient.playlist.write() {
        // A slower, older request must not replace a newer playlist.
        if generation > playlist.0 {
            *playlist = (generation, paths);
        }
    }
    Ok(Playlist { generation, tracks, unavailable: built.unavailable, truncated: built.truncated })
}

/// Title, artist and album from a track's tags, for the music capsule.
#[tauri::command]
pub async fn ambient_track_info(ambient: State<'_, AmbientState>, generation: u64, id: usize) -> AppResult<TrackDetails> {
    let Some(path) = ambient.track(generation, id) else {
        return Ok(TrackDetails { title: None, artist: None, album: None });
    };
    blocking(move || {
        let info = formats::read_track(&path, false);
        Ok(TrackDetails { title: info.title, artist: info.artist.or(info.album_artist), album: info.album })
    })
    .await
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn playable_formats() {
        assert!(is_playable(Path::new("C:/Music/01 Song.MP3")));
        assert!(is_playable(Path::new("a.flac")));
        assert!(!is_playable(Path::new("a.wma")));
        assert!(!is_playable(Path::new("cover.jpg")));
        assert_eq!(mime_type(Path::new("x.Opus")), "audio/ogg");
        assert_eq!(mime_type(Path::new("x.m4a")), "audio/mp4");
    }

    #[test]
    fn stale_generations_are_refused() {
        let state = AmbientState::default();
        *state.playlist.write().unwrap() = (3, vec![PathBuf::from("a.mp3")]);
        assert_eq!(state.track(3, 0), Some(PathBuf::from("a.mp3")));
        assert_eq!(state.track(2, 0), None);
        assert_eq!(state.track(3, 1), None);
    }
}
